function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('.menu').each((_, menuRoot) => {
    $(menuRoot).find('.menu-section').each((_, secEl) => {
      // Skip sections that have a description (treated as add‑ons/extras)
      if ($(secEl).find('.menu-section-description').length) {
        return;
      }

      const sectionTitle = cleanText(
        $(secEl).find('.menu-section-header .menu-section-title').text()
      ) || null;

      $(secEl).find('.menu-item').each((_, itemEl) => {
        const nameRaw = cleanText($(itemEl).find('.menu-item-title').text());
        if (!nameRaw) return;
        // Remove any leading numbering like "12. "
        const name = nameRaw.replace(/^\d+\s*\.\s*/, '');

        const descEl = $(itemEl).find('.menu-item-description');
        const description = descEl.length ? cleanText(descEl.text()) : null;

        // Prefer the top price; fall back to bottom if needed
        let priceNum = null;
        const priceTop = $(itemEl).find('.menu-item-price-top');
        if (priceTop.length) {
          priceNum = parsePrice(cleanText(priceTop.text()));
        }
        if (priceNum === null) {
          const priceBottom = $(itemEl).find('.menu-item-price-bottom');
          if (priceBottom.length) {
            priceNum = parsePrice(cleanText(priceBottom.text()));
          }
        }

        const key = `${sectionTitle}|${name}|${description || ''}|${priceNum}`;
        if (!seen.has(key)) {
          seen.add(key);
          items.push({
            section: sectionTitle,
            name,
            description,
            price: priceNum
          });
        }
      });
    });
  });

  return items;
}
```

